import 'package:flutter_voximplant/flutter_voximplant.dart';

VIClient client = Voximplant().getClient();
await client.connect(node: VINode.NodeX);
VIAuthResult auth = await client.login('user', 'pass');
VICall call = await client.call('123456');
call.onCallConnected = (call, headers) => print('connected');
